using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly ModelMetricsResponse _metrics;
    private readonly string[] _categoryNames;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 0);

        IDataView dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label")
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(dataView);

        // Evaluate using cross-validation for small datasets
        var cvResults = _mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3);
        var avgMetrics = new
        {
            MacroAccuracy = cvResults.Average(r => r.Metrics.MacroAccuracy),
            MicroAccuracy = cvResults.Average(r => r.Metrics.MicroAccuracy),
            LogLoss = cvResults.Average(r => r.Metrics.LogLoss),
            LogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction),
        };

        // Also get per-class metrics from the full-data model
        IDataView predictions = _model.Transform(dataView);
        var fullMetrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        _categoryNames = GetCategoryNames(dataView);

        _metrics = new ModelMetricsResponse
        {
            MacroAccuracy = Math.Round(avgMetrics.MacroAccuracy, 4),
            MicroAccuracy = Math.Round(avgMetrics.MicroAccuracy, 4),
            LogLoss = Math.Round(avgMetrics.LogLoss, 4),
            LogLossReduction = Math.Round(avgMetrics.LogLossReduction, 4),
            PerCategoryMetrics = fullMetrics.PerClassLogLoss
                .Select((logLoss, i) => new CategoryMetric
                {
                    Category = i < _categoryNames.Length ? _categoryNames[i] : $"Class {i}",
                    Precision = i < fullMetrics.ConfusionMatrix.PerClassPrecision.Count
                        ? Math.Round(fullMetrics.ConfusionMatrix.PerClassPrecision[i], 4) : 0,
                    Recall = i < fullMetrics.ConfusionMatrix.PerClassRecall.Count
                        ? Math.Round(fullMetrics.ConfusionMatrix.PerClassRecall[i], 4) : 0,
                })
                .ToList()
        };

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _categoryNames.Length; i++)
        {
            scores[_categoryNames[i]] = (float)Math.Round(prediction.Score[i], 4);
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Scores = scores
        };
    }

    public ModelMetricsResponse GetMetrics() => _metrics;

    private string[] GetCategoryNames(IDataView dataView)
    {
        var column = dataView.Schema["Label"];
        VBuffer<ReadOnlyMemory<char>> keyValues = default;
        // The Label column is mapped to a key; retrieve the original string values
        var labelCol = _model.GetOutputSchema(dataView.Schema)["Label"];
        labelCol.GetKeyValues(ref keyValues);
        return keyValues.DenseValues().Select(v => v.ToString()).ToArray();
    }
}

